CREATE TABLE `ici` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `establecimiento_id` int(11) NOT NULL,
  `producto_id` int(11) NOT NULL,
  `anio` smallint(6) NOT NULL,
  `mes` tinyint(4) NOT NULL,
  `consumo` decimal(14,2) NOT NULL DEFAULT 0.00,
  `stock_final` decimal(14,2) DEFAULT NULL,
  `precio` decimal(14,4) DEFAULT 0.0000,
  `cpa_sismed` decimal(14,2) DEFAULT NULL,
  `situacion_sismed` varchar(20) DEFAULT NULL,
  `importacion_id` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_ici` (`establecimiento_id`,`producto_id`,`anio`,`mes`),
  KEY `importacion_id` (`importacion_id`),
  KEY `idx_ici_periodo` (`anio`,`mes`),
  KEY `idx_ici_prod` (`producto_id`),
  CONSTRAINT `ici_ibfk_1` FOREIGN KEY (`establecimiento_id`) REFERENCES `establecimiento` (`id`),
  CONSTRAINT `ici_ibfk_2` FOREIGN KEY (`producto_id`) REFERENCES `producto` (`id`),
  CONSTRAINT `ici_ibfk_3` FOREIGN KEY (`importacion_id`) REFERENCES `importacion` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=59895 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

