  `valor_resuelto` decimal(14,2) DEFAULT NULL,
  `creado` datetime NOT NULL DEFAULT current_timestamp(),
  `detectado_inicial` tinyint(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
