  CONSTRAINT `incidencia_stock_ibfk_4` FOREIGN KEY (`resuelto_importacion_id`) REFERENCES `importacion` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=15 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
