DROP TABLE IF EXISTS `producto`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `producto` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `medcod` varchar(20) NOT NULL,
  `nombre` varchar(200) NOT NULL,
  `nombre_abrev` varchar(100) DEFAULT NULL,
  `presentacion` varchar(100) DEFAULT NULL,
  `concentracion` varchar(60) DEFAULT NULL,
  `forma_farma` varchar(30) DEFAULT NULL,
  `tipo` varchar(5) DEFAULT NULL,
  `es_petitorio` tinyint(1) DEFAULT NULL,
  `es_estrategico` tinyint(1) DEFAULT NULL,
  `controlado` tinyint(1) DEFAULT NULL,
  `stock_min` int(11) DEFAULT NULL,
  `stock_max` int(11) DEFAULT NULL,
  `punto_reposicion` int(11) DEFAULT NULL,
  `reg_sanitario` varchar(30) DEFAULT NULL,
  `activo` tinyint(1) DEFAULT 1,
  `medpet` varchar(5) DEFAULT NULL,
  `medest` varchar(5) DEFAULT NULL,
  `codigo_siga` varchar(20) DEFAULT NULL,
  `origen` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `medcod` (`medcod`),
  KEY `idx_prod_nombre` (`nombre`)
) ENGINE=InnoDB AUTO_INCREMENT=792 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
