CREATE TABLE `stg_stock_almacen` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `importacion_id` int(11) NOT NULL,
  `almcod` varchar(20) DEFAULT NULL,
  `medcod` varchar(20) DEFAULT NULL,
  `medlote` varchar(80) DEFAULT NULL,
  `medfechvto` varchar(20) DEFAULT NULL,
  `stksaldode` varchar(20) DEFAULT NULL,
  `stkprecio` varchar(20) DEFAULT NULL,
  `medregsan` varchar(80) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `importacion_id` (`importacion_id`),
  KEY `idx_stg_stkalm` (`medcod`,`medlote`),
  CONSTRAINT `stg_stock_almacen_ibfk_1` FOREIGN KEY (`importacion_id`) REFERENCES `importacion` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=40623 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
