--
-- Table structure for table `stock_fuera_catalogo`
--

DROP TABLE IF EXISTS `stock_fuera_catalogo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `stock_fuera_catalogo` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `origen` varchar(10) NOT NULL,
  `almacen_cod` varchar(20) DEFAULT NULL,
  `establecimiento_id` int(11) DEFAULT NULL,
  `medcod` varchar(20) NOT NULL,
  `lote` varchar(80) NOT NULL,
  `fecha_vcto` date DEFAULT NULL,
  `cantidad` decimal(14,2) NOT NULL,
  `precio` decimal(14,4) DEFAULT NULL,
  `reg_sanitario` varchar(80) DEFAULT NULL,
  `periodo` date DEFAULT NULL,
  `importacion_id` int(11) DEFAULT NULL,
  `actualizado` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `establecimiento_id` (`establecimiento_id`),
  KEY `importacion_id` (`importacion_id`),
